#include <bits/stdc++.h>
using namespace std;

// KMP over the non-zero sign stream; each full match adds `amount` at that price index.
void kmpEvents(const vector<pair<int, int>> &signs, const vector<int> &pat, vector<long long> &delta, int amount) {
    int m = pat.size();
    vector<int> pi(m, 0);
    for (int i = 1; i < m; i++) {
        int j = pi[i - 1];
        while (j && pat[i] != pat[j]) j = pi[j - 1];
        if (pat[i] == pat[j]) j++;
        pi[i] = j;
    }
    int j = 0;
    for (auto [sign, idx] : signs) {
        while (j && sign != pat[j]) j = pi[j - 1];
        if (sign == pat[j]) j++;
        if (j == m) { delta[idx] += amount; j = pi[j - 1]; }
    }
}

