import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    // KMP over the non-zero sign stream; each full match adds `amount` at that price index.
    static void kmpEvents(int[] sign, int[] idx, int cnt, int[] pat, long[] delta, int amount) {
        int m = pat.length;
        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && pat[i] != pat[j]) j = pi[j - 1];
            if (pat[i] == pat[j]) j++;
            pi[i] = j;
        }
        int j = 0;
        for (int t = 0; t < cnt; t++) {
            while (j > 0 && sign[t] != pat[j]) j = pi[j - 1];
            if (sign[t] == pat[j]) j++;
            if (j == m) { delta[idx[t]] += amount; j = pi[j - 1]; }
        }
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), b = (int) nextLong(), s = (int) nextLong();
        long[] p = new long[n];
        for (int i = 0; i < n; i++) p[i] = nextLong();
        int[] buy = new int[b], sell = new int[s];
        for (int i = 0; i < b; i++) buy[i] = (int) nextLong();
        for (int i = 0; i < s; i++) sell[i] = (int) nextLong();
        // equal prices produce no signal and do not break the sequence
        int[] sign = new int[n], idx = new int[n];
        int cnt = 0;
        for (int i = 1; i < n; i++)
            if (p[i] != p[i - 1]) { sign[cnt] = p[i] > p[i - 1] ? 1 : -1; idx[cnt++] = i; }
        long[] delta = new long[n];
        kmpEvents(sign, idx, cnt, buy, delta, 1);
        kmpEvents(sign, idx, cnt, sell, delta, -1);
        StringBuilder out = new StringBuilder();
        long pos = 0;
        for (int i = 0; i < n; i++) {
            pos += delta[i];
            if (i > 0) out.append(' ');
            out.append(pos);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

type signal struct{ sign, idx int }

// kmpEvents runs KMP over the non-zero sign stream; each full match adds amount at that price index.
func kmpEvents(signs []signal, pat []int, delta []int64, amount int64) {
	m := len(pat)
	pi := make([]int, m)
	for i := 1; i < m; i++ {
		j := pi[i-1]
		for j > 0 && pat[i] != pat[j] {
			j = pi[j-1]
		}
		if pat[i] == pat[j] {
			j++
		}
		pi[i] = j
	}
	j := 0
	for _, sg := range signs {
		for j > 0 && sg.sign != pat[j] {
			j = pi[j-1]
		}
		if sg.sign == pat[j] {
			j++
		}
		if j == m {
			delta[sg.idx] += amount
			j = pi[j-1]
		}
	}
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, b, s := nextInt(), nextInt(), nextInt()
	p := make([]int, n)
	for i := range p {
		p[i] = nextInt()
	}
	buy := make([]int, b)
	for i := range buy {
		buy[i] = nextInt()
	}
	sell := make([]int, s)
	for i := range sell {
		sell[i] = nextInt()
	}
	// equal prices produce no signal and do not break the sequence
	var signs []signal
	for i := 1; i < n; i++ {
		if p[i] > p[i-1] {
			signs = append(signs, signal{1, i})
		} else if p[i] < p[i-1] {
			signs = append(signs, signal{-1, i})
		}
	}
	delta := make([]int64, n)
	kmpEvents(signs, buy, delta, 1)
	kmpEvents(signs, sell, delta, -1)
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	var pos int64
	for i := 0; i < n; i++ {
		pos += delta[i]
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(pos, 10))
	}
	w.WriteByte('\n')
}
